<?php
/**
 * Registers every block produced by the build.
 *
 * @package Mdev\Gb
 */

declare( strict_types=1 );

namespace Mdev\Gb\Blocks;

/**
 * Registers all blocks listed in the generated blocks manifest.
 *
 * `npm run build` compiles each folder under `blocks/` into `build/` and writes
 * `build/blocks-manifest.php`, so new blocks need no PHP changes.
 *
 * @since 0.1.0
 */
final class BlockRegistrar {

	/**
	 * Manifest file name generated by `wp-scripts build --blocks-manifest`.
	 *
	 * @since 0.1.0
	 */
	public const MANIFEST = 'blocks-manifest.php';

	/**
	 * Constructor.
	 *
	 * @since 0.1.0
	 *
	 * @param string $build_dir Absolute path to the compiled blocks directory.
	 */
	public function __construct( private readonly string $build_dir ) {
	}

	/**
	 * Register the block types. Hooked to `init`.
	 *
	 * Silently does nothing when assets have not been built yet, so a fresh
	 * checkout never fatals.
	 *
	 * @since 0.1.0
	 *
	 * @return void
	 */
	public function register(): void {
		$manifest = $this->build_dir . '/' . self::MANIFEST;

		if ( ! is_readable( $manifest ) ) {
			return;
		}

		wp_register_block_types_from_metadata_collection( $this->build_dir, $manifest );
	}
}
